 3	public final class BubbleSort {
 4	
 5	    private BubbleSort() {
 6	        // Utility class.
 7	    }
 8	
 9	    public static void sortInPlace(int[] values) {
10	        validate(values);
11	        sortValuesInPlace(values);
12	    }
13	
14	    public static int[] sortedCopy(int[] values) {
15	        validate(values);
16	
17	        int[] copy = Arrays.copyOf(values, values.length);
18	        sortValuesInPlace(copy);
19	        return copy;
20	    }
21	
22	    private static void validate(int[] values) {
23	        if (values == null) {
24	            throw new IllegalArgumentException("values must not be null");
25	        }
26	    }
27	
28	    private static void sortValuesInPlace(int[] values) {
29	        for (int end = values.length - 1; end > 0; end--) {
30	            boolean swapped = false;
31	
32	            for (int index = 0; index < end; index++) {
33	                if (values[index] > values[index + 1]) {
34	                    swap(values, index, index + 1);
35	                    swapped = true;
36	                }
37	            }
38	
39	            if (!swapped) {
40	                return;
41	            }
42	        }
43	    }
44	
45	    private static void swap(int[] values, int leftIndex, int rightIndex) {
46	        int temp = values[leftIndex];
47	        values[leftIndex] = values[rightIndex];
48	        values[rightIndex] = temp;
49	    }
50	}

